def distribute(i, kids, best):
    if i == len(cookies):
        best[0] = min(best[0], max(kids))      # a complete distribution
        return
    seen = set()
    for j in range(len(kids)):
        if kids[j] in seen or kids[j] + cookies[i] >= best[0]:
            continue                           # same as another child, or cannot beat best
        seen.add(kids[j])
        kids[j] += cookies[i]
        distribute(i + 1, kids, best)
        kids[j] -= cookies[i]

